import'dart:async';import'package:dierb_api_client/dierb_api_client.dart';import'package:flutter/material.dart';class OrderConversationPage extends StatefulWidget{const OrderConversationPage({super.key,required this.orderId});final String orderId;@override State<OrderConversationPage>createState()=>_State();}class _State extends State<OrderConversationPage>{final api=DierbApi(),input=TextEditingController();List<dynamic>messages=const[];String uid='';bool sending=false;Timer?timer;@override void initState(){super.initState();start();}Future<void>start()async{uid=(await api.profile())['id'].toString();await load();timer=Timer.periodic(const Duration(seconds:5),(_)=>load());}Future<void>load()async{try{final v=await api.chatMessages(widget.orderId);if(mounted)setState(()=>messages=v);}catch(_){}}Future<void>send({String?preset,String type='text'})async{final body=(preset??input.text).trim();if(body.isEmpty)return;setState(()=>sending=true);try{await api.sendChatMessage(widget.orderId,body,type:type);input.clear();await load();}finally{if(mounted)setState(()=>sending=false);}}@override void dispose(){timer?.cancel();api.close();input.dispose();super.dispose();}@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('التواصل مع العميل')),body:Column(children:[Padding(padding:const EdgeInsets.all(10),child:SizedBox(width:double.infinity,child:FilledButton.tonalIcon(onPressed:sending?null:()=>send(preset:'المندوب وصل لمكان التسليم',type:'arrived'),icon:const Icon(Icons.location_on),label:const Text('إبلاغ العميل: وصلت')))),Expanded(child:messages.isEmpty?const Center(child:Text('ابدأ التواصل مع العميل')):ListView.builder(reverse:true,itemCount:messages.length,itemBuilder:(_,i){final m=Map<String,dynamic>.from(messages[i]as Map),mine=m['senderId']==uid;return Align(alignment:mine?AlignmentDirectional.centerStart:AlignmentDirectional.centerEnd,child:Card(color:m['type']=='arrived'?const Color(0xFFFFE8B5):mine?const Color(0xFFDCEFE6):null,child:Padding(padding:const EdgeInsets.all(12),child:Text((m['body']??'').toString()))));})),SafeArea(top:false,child:Padding(padding:const EdgeInsets.all(10),child:Row(children:[Expanded(child:TextField(controller:input,decoration:const InputDecoration(hintText:'اكتب رسالة...'))),IconButton.filled(onPressed:sending?null:send,icon:const Icon(Icons.send))])))]));}
